t.script:
const challengeToken =
    document
        .getElementById('qr-login-data')
        .dataset
        .token;

async function pollLogin() {

    const response = await fetch(
        `/qr-login/status/${challengeToken}`,
        {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: '{}',
        }
    );

    const data = await response.json();

    console.log(data);

    if (!data.result) {
        return;
    }

    if (
        data.result.status === 'approved'
    ) {

        window.location =
            `/qr-login/finalize/${challengeToken}`;

    }

    if (
        data.result.status === 'rejected'
    ) {

        document.getElementById(
            'login-status'
        ).innerHTML =
            'Login Rejected';

    }

}

setInterval(pollLogin, 2000);
